\\\n    collator = DataCollatorForSeq2Seq(tokenizer=tokenizer, padding=True)\\\\n\\\\n    is_dryrun = args.max_steps > 0\\\\n    ta = {\\\\n        \\\\\\\"output_dir\\\\\\\": args.output_dir,\\\\n        \\\\\\\"num_train_epochs\\\\\\\": args.epochs,\\\\n        \\\\\\\"max_steps\\\\\\\": args.max_steps,\\\\n        \\\\\\\"per_device_train_batch_size\\\\\\\": args.batch_size,\\\\n        \\\\\\\"per_device_eval_batch_size\\\\\\\": args.batch_size,\\\\n        \\\\\\\"gradient_accumulation_steps\\\\\\\": args.grad_accumulation,\\\\n        \\\\\\\"learning_rate\\\\\\\": args.lr,\\\\n        \\\\\\\"warmup_ratio\\\\\\\": args.warmup_ratio,\\\\n        \\\\\\\"bf16\\\\\\\": True,\\\\n        \\\\\\\"logging_steps\\\\\\\": 1 if is_dryrun else 50,\\\\n        \\\\\\\"eval_strategy\\\\\\\": \\\\\\\"no\\\\\\\" if is_dryrun else \\\\\\\"epoch\\\\\\\",\\\\n        \\\\\\\"save_strategy\\\\\\\": \\\\\\\"no\\\\\\\" if is_dryrun else \\\\\\\"epoch\\\\\\\",\\\\n        \\\\\\\"load_best_model_at_end\\\\\\\": not is_dryrun,\\\\n        \\\\\\\"save_total_limit\\\\\\\": 2,\\\\n        \\\\\\\"seed\\\\\\\": args.seed,\\\\n        \\\\\\\"run_name\\\\\\\": args.run_name,\\\\n        \\\\\\\"report_to\\\\\\\": \\\\\\\"none\\\\\\\" if args.no_wandb else \\\\\\\"wandb\\\\\\\",\\\\n        \\\\\\\"gradient_checkpointing\\\\\\\": True,\\\\n        \\\\\\\"dataloader_num_workers\\\\\\\": 4,\\\\n    }\\\\n    if not is_dryrun:\\\\n        ta[\\\\\\\"metric_for_best_model\\\\\\\"] = \\\\\\\"eval_loss\\\\\\\"\\\\n        ta[\\\\\\\"greater_is_better\\\\\\\"] = False\\\\n    training_args = TrainingArguments(**ta)\\\\n\\\\n    trainer = Trainer(\\\\n        model=model,\\\\n        args=training_args,\\\\n        train_dataset=train_ds,\\\\n        eval_dataset=val_ds,\\\\n        data_collator=collator,\\\\n    )\\\\n\\\\n    log.info(\\\\\\\"Starting training...\\\\\\\")\\\\n    trainer.train()\\\\n\\\\n    if not is_dryrun:\\\\n        best_dir = os.path.join(args.output_dir, \\\\\\\"best\\\\\\\")\\\\n        trainer.save_model(best_dir)\\\\n        tokenizer.save_pretrained(best_dir)\\\\n        log.info(f\\\\\\\"Best model saved to {best_dir}\\\\\\\")\\\\n    else:\\\\n        log.info(\\\\\\\"Dry-run complete.\\\\\\\")\\\\n\\\\n\\\\nif __name__ == \\\\\\\"__main__\\\\\\\":\\\\n    main()\\\\n\\\", \\\"stderr\\\": \\\"\\\", \\\"return_code\\\": 0}, \\\"error\\\": null, \\\"metadata\\\": {\\\"elapsed_seconds\\\": 1.69}}\"}","structuredContent":{"result":"{\"success\": true, \"data\": {\"stdout\": \"# train_verifier.py — Qwen3 LoRA fine-tuning for code-test pass/fail classification\\n# Input: data_dir/ with {train,val}.jsonl (fields: code, test, label 0=fail/1=pass)\\n# Output: LoRA adapter in output_dir/best/\\n# Deps: torch, transformers, peft, datasets, wandb\\n\\nimport argparse\\nimport json\\nimport logging\\nimport os\\n\\nimport torch\\nfrom datasets import Dataset\\nfrom peft import LoraConfig, TaskType, get_peft_model\\nfrom transformers import (\\n    AutoModelForCausalLM,\\n    AutoTokenizer,\\n    DataCollatorForSeq2Seq,\\n    Trainer,\\n    TrainingArguments,\\n)\\n\\nlogging.basicConfig(level=logging.INFO, format=\\\"%(asctime)s %(levelname)s %(message)s\\\")\\nlog = logging.getLogger(__name__)\\n\\nSYSTEM_PROMPT = (\\n    \\\"You are a code verifier. Given a code snippet and a test case, \\\"\\n    \\\"predict whether the test will pass or fail.\\\"\\n)\\nLABEL_MAP = {1: \\\"pass\\\", 0: \\\"fail\\\"}\\n\\n\\ndef load_jsonl(path):\\n    with open(path) as f:\\n        return [json.loads(line) for line in f]\\n\\n\\ndef detect_thinking_support(tokenizer):\\n    \\\"\\\"\\\"Qwen3 tokenizers support enable_thinking; older ones don't.\\\"\\\"\\\"\\n    try:\\n        tokenizer.apply_chat_template(\\n            [{\\\"role\\\": \\\"user\\\", \\\"content\\\": \\\"hi\\\"}],\\n            tokenize=False,\\n            enable_thinking=False,\\n        )\\n        return {\\\"enable_thinking\\\": False}\\n    except TypeError:\\n        return {}\\n\\n\\ndef build_messages(code, test, answer=None):\\n    user_msg = f\\\"## Code\\\\n{code}\\\\n\\\\n## Test\\\\n{test}\\\\n\\\\nWill this test pass or fail?\\\"\\n    msgs = [\\n        {\\\"role\\\": \\\"system\\\", \\\"content\\\": SYSTEM_PROMPT},\\n        {\\\"role\\\": \\\"user\\\", \\\"content\\\": user_msg},\\n    ]\\n    if answer is not None:\\n        msgs.append({\\\"role\\\": \\\"assistant\\\", \\\"content\\\": answer})\\n    return msgs\\n\\n\\ndef tokenize_example(tokenizer, code, test, label, max_len, tmpl_kw):\\n    answer = LABEL_MAP[label]\\n\\n    prompt_ids = tokenizer.apply_chat_template(\\n        build_messages(code, test),\\n        tokenize=True, add_generation_prompt=True, **tmpl_kw,\\n    )\\n    full_ids = tokenizer.apply_chat_template(\\n        build_messages(code, test, answer),\\n        tokenize=True, add_generation_prompt=False, **tmpl_kw,\\n    )\\n\\n    truncated = len(full_ids) > max_len\\n    if truncated:\\n        full_ids = full_ids[:max_len]\\n\\n    prompt_len = min(len(prompt_ids), len(full_ids))\\n    labels = [-100] * prompt_len + full_ids[prompt_len:]\\n\\n    return {\\n        \\\"input_ids\\\": full_ids,\\n        \\\"labels\\\": labels,\\n        \\\"attention_mask\\\": [1] * len(full_ids),\\n    }, truncated\\n\\n\\ndef preprocess_split(tokenizer, data, max_len, name, tmpl_kw):\\n    out = {\\\"input_ids\\\": [], \\\"labels\\\": [], \\\"attention_mask\\\": []}\\n    n_trunc = 0\\n    for ex in data:\\n        tok, trunc = tokenize_example(\\n            tokenizer, ex[\\\"code\\\"], ex[\\\"test\\\"], ex[\\\"label\\\"], max_len, tmpl_kw,\\n        )\\n        for k in out:\\n            out[k].append(tok[k])\\n        n_trunc += int(trunc)\\n    pct = n_trunc / len(data) * 100 if data else 0\\n    log.info(f\\\"{name}: {n_trunc}/{len(data)} truncated ({pct:.1f}%)\\\")\\n    return Dataset.from_dict(out)\\n\\n\\ndef main():\\n    p = argparse.ArgumentParser(description=\\\"Train Qwen3 LoRA verifier\\\")\\n   